def frameProjectionOverlap (n : ℕ) (J : EuclideanSpace ℝ (MomentIndex n) →L[ℝ] G)
    (S : Submodule ℝ G) [S.HasOrthogonalProjection] : ℝ :=
  ((2 : ℝ) ^ n)⁻¹ * ∑ i, ‖S.orthogonalProjectionOnto (J (WithLp.toLp 2 (Pi.single i 1)))‖ ^ 2

